  ],
  "claims": [
    {
      "claim": "Direct human patch testing showed a strong (++) allergic reaction to bis-EMA (the query) in a manicurist, and another patient had allergic reactions to bis-EMA before symptoms from a bis-EMA-containing temporary crown paste.",
      "card_ids": ["C26"]
    },
    {
      "claim": "Human patch tests were positive for structurally related dimethacrylates: diethylene glycol dimethacrylate (C01), ethylene glycol dimethacrylate (C02, C08, C28, C38, C39), and triethylene glycol dimethacrylate (C10, C34, C40).",
      "card_ids": ["C01","C02","C08","C10","C28","C34","C38","C39","C40"]
    },
    {
      "claim": "Human patch tests were positive for methacrylate monomers 2-hydroxyethyl methacrylate (C09, C21, C36, C44), 2-hydroxypropyl methacrylate (C33, C41), glycidyl methacrylate (C27), and 2-(acetoacetoxy)ethyl methacrylate (C07); propyl methacrylate showed cross-reactivity (C30, C35).",
      "card_ids": ["C07","C09","C21","C27","C30","C33","C35","C36","C41","C44"]
    },
    {
      "claim": "Guinea pig tests identified cyclohexyl methacrylate as a moderate sensitizer (C11, C20, C24, C37) and demonstrated cross-sensitization among methacrylates and neopentyl acrylate (C22, C31), including a positive cross-reaction to butyl methacrylate (C29).",
      "card_ids": ["C11","C20","C22","C24","C29","C31","C37"]
    },
    {
      "claim": "L4 phototoxicity/irritation/local-damage records are out of scope for the sensitization label; C57 and C65 show EGDMA and MMA were not irritant in an ear-weight assay, but lack of irritation does not indicate lack of sensitization, and C66 contains only an incidental LLNA negative for 6:2 FTMAC, a structurally distinct mono-methacrylate that is not transferable to bis-EMA.",
      "card_ids": ["C57","C65","C66"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "phototoxicity_irritation_local_damage",
      "applicability": "low",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C57","C58","C59","C60","C61","C62","C63","C64","C65","C66","C67","C68"]
    }
  ],
  "evidence_gaps": [
    "No validated negative human or animal sensitization result for bis-EMA.",
    "No quantitative potency data such as an LLNA EC3 for the query.",
    "L4 records are local irritation/phototoxicity/injury outcomes and cannot define the sensitization label.",
    "The incidental LLNA negative for 6:2 FTMAC (C66) is for a structurally distinct mono-methacrylate and is not transferable to the bis-EMA query.",
    "Skin exposure context is mixed or unclear; the large lipophilic molecule may have limited penetration, but direct human positives exist."
  ],
  "decision_summary": "Direct human patch-test evidence for bis-EMA (C26) and multiple positive human outcomes for structurally related methacrylate and dimethacrylate monomers support the risk class. L4 phototoxicity/irritation/local-damage records are out of scope and do not alter the decision. Prediction: risk, high confidence."
}

